function evalGlyph(params, inputs, t) {
  /* why: Make a gizmo that makes text from an image. The melt in
     miniature - an image becomes the characters for it. */
  var f = inputs.field;
  var ramp = " .:-=+*#%@";
  var cols = Math.round(params.cols), rows = Math.round(params.rows);
  var text = "", ink = 0, n = 0;
  if (!f) return { text: "", ink: 0 };
  for (var j = 0; j < rows; j++) {
    for (var i = 0; i < cols; i++) {
      var v = f((i + 0.5) / cols, (j + 0.5) / rows);
      v = v < 0 ? 0 : v > 1 ? 1 : v;
      v = Math.pow(v, params.gamma);
      ink += v; n += 1;
      text += ramp.charAt(Math.min(ramp.length - 1, Math.floor(v * ramp.length)));
    }
    text += "\n";
  }
  return { text: text, ink: n ? ink / n : 0 };
}
